// API names below assume Jinx UI's standard Drawer/Menu surface; adjust if the package differs.
import { useState } from 'react';
import { Button, Drawer, Menu, MenuItem, Divider } from '@jinx-ui/react';

export type NavKey = 'projects' | 'team' | 'settings' | 'logout';

export interface AppNavProps {
  onNavigate: (key: NavKey) => void;
}

const NAV_ITEMS: ReadonlyArray<{ key: NavKey; label: string }> = [
  { key: 'projects', label: 'Проекты' },
  { key: 'team', label: 'Команда' },
  { key: 'settings', label: 'Настройки' },
];

export default function AppNav({ onNavigate }: AppNavProps) {
  const [open, setOpen] = useState(false);

  const handleSelect = (key: NavKey) => {
    onNavigate(key);
    setOpen(false);
  };

  return (
    <>
      <Button variant="secondary" onClick={() => setOpen(true)} aria-expanded={open}>
        Меню
      </Button>

      <Drawer
        open={open}
        placement="left"
        title="Навигация"
        onClose={() => setOpen(false)}
      >
        <Menu aria-label="Основная навигация">
          {NAV_ITEMS.map((item) => (
            <MenuItem key={item.key} onSelect={() => handleSelect(item.key)}>
              {item.label}
            </MenuItem>
          ))}

          <Divider />

          <MenuItem tone="danger" onSelect={() => handleSelect('logout')}>
            Выйти
          </MenuItem>
        </Menu>
      </Drawer>
    </>
  );
}

